// Static Examples page generator: `node tools/build-examples-pages.mjs`.
//
// Reads content from examples-content.mjs, matches each entry against the
// live examples manifest (sketch/js/examples-data.js, itself generated by
// tools/build-examples.mjs from Examples/**/*.json), and writes static
// pages under example-setups/ (NOT examples/ — this repo's source scene
// files live in Examples/, and Examples/ and examples/ are the same
// directory on any case-insensitive filesystem, macOS/APFS included; a
// same-name output directory would silently write generated files into the
// source directory for anyone working locally on one):
//   - example-setups/<slug>/index.html  (background, honest "what you
//     won't see" limitations, references, and a locked, click-to-inspect
//     embed of the actual example scene)
//   - example-setups/index.html         (hub page: card grid grouped like
//     the in-app Examples dropdown)
// The public URL is still /example-setups/ — deliberately not reusing
// /examples/ even though GitHub Pages itself is case-sensitive, so the
// on-disk path and the served path always match exactly.
//
// Not every example needs an entry in examples-content.mjs — same rule as
// the wiki: a curated example with no content entry still works fine from
// the in-app dropdown, it just doesn't get a public page yet. Re-run this
// after editing examples-content.mjs, and after re-running
// tools/build-examples.mjs (an example's slug must exist in
// sketch/js/examples-data.js before a page can be built for it — the
// validation below throws otherwise, catching a typo'd `match` or a
// renamed/removed example file instead of silently shipping a stale page).

import { mkdir, writeFile, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { registry, createElement, getSize } from '../sketch/js/elements.js';
// Registers the redesigned detector catalogue and the Etalon/VIPA element
// onto `registry`, same reason tools/build-wiki.mjs imports these: a
// related-component link to one of these types needs its live icon/label.
import '../sketch/js/detector-instruments.js';
import '../sketch/js/etalon.js';
import '../sketch/js/vipa.js';
import { examples } from '../sketch/js/examples-data.js';
import { exampleEntries } from './examples-content.mjs';
import { WIKI_TYPES } from '../sketch/js/wiki-types.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = join(ROOT, 'example-setups');
const SITE_URL = 'https://opticalsetup.com';

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function iconSVG(type) {
  const def = registry[type];
  const el = createElement(type);
  const sz = getSize(el);
  const vb = Math.max(sz.w, sz.h) + 12;
  return `<svg viewBox="${-vb / 2} ${-vb / 2} ${vb} ${vb}" aria-hidden="true">${def.svg(el)}</svg>`;
}

const brandMark = () => `
  <svg class="brand-mark" viewBox="0 0 130 85" aria-hidden="true">
    <g class="mark-accent" stroke-width="4" stroke-linecap="round">
      <line x1="22" y1="45" x2="29" y2="45"/>
      <line x1="20.8" y1="47.8" x2="25.8" y2="52.8"/>
      <line x1="18" y1="49" x2="18" y2="56"/>
      <line x1="15.2" y1="47.8" x2="10.2" y2="52.8"/>
      <line x1="14" y1="45" x2="7" y2="45"/>
      <line x1="15.2" y1="42.2" x2="10.2" y2="37.2"/>
      <line x1="18" y1="41" x2="18" y2="34"/>
      <line x1="20.8" y1="42.2" x2="25.8" y2="37.2"/>
    </g>
    <line class="mark-accent" x1="29" y1="45" x2="77" y2="45" stroke-width="4" stroke-linecap="round"/>
    <polygon class="mark-ink" points="64,12 42,68 86,68" fill="none" stroke-width="4.5" stroke-linejoin="round"/>
    <g class="mark-accent" stroke-width="2.4" stroke-linecap="round">
      <line x1="77" y1="45" x2="108" y2="22"/>
      <line x1="77" y1="45" x2="108" y2="34"/>
      <line x1="77" y1="45" x2="108" y2="45"/>
      <line x1="77" y1="45" x2="108" y2="56"/>
      <line x1="77" y1="45" x2="108" y2="68"/>
    </g>
    <line class="mark-ink" x1="108" y1="14" x2="108" y2="76" stroke-width="4" stroke-linecap="round"/>
    <g class="mark-ink" stroke-width="3" stroke-linecap="round">
      <line x1="108" y1="22" x2="115" y2="22"/>
      <line x1="108" y1="34" x2="115" y2="34"/>
      <line x1="108" y1="45" x2="115" y2="45"/>
      <line x1="108" y1="56" x2="115" y2="56"/>
      <line x1="108" y1="68" x2="115" y2="68"/>
    </g>
  </svg>`;

const FAVICON = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 130 85'%3E%3Cg stroke='%231361fa' stroke-width='6' stroke-linecap='round'%3E%3Cline x1='22' y1='45' x2='29' y2='45'/%3E%3Cline x1='18' y1='49' x2='18' y2='56'/%3E%3Cline x1='14' y1='45' x2='7' y2='45'/%3E%3Cline x1='18' y1='41' x2='18' y2='34'/%3E%3C/g%3E%3Cline x1='29' y1='45' x2='77' y2='45' stroke='%231361fa' stroke-width='6' stroke-linecap='round'/%3E%3Cpolygon points='64,12 42,68 86,68' fill='none' stroke='%230a1a33' stroke-width='7' stroke-linejoin='round'/%3E%3Cg stroke='%231361fa' stroke-width='4' stroke-linecap='round'%3E%3Cline x1='77' y1='45' x2='112' y2='28'/%3E%3Cline x1='77' y1='45' x2='112' y2='45'/%3E%3Cline x1='77' y1='45' x2='112' y2='62'/%3E%3C/g%3E%3C/svg%3E";

function header(base) {
  return `
  <header class="site-header">
    <a class="brand" href="${base}/">${brandMark()}<span class="brand-ink">Optical</span><span class="brand-accent">Setup</span></a>
    <div class="header-actions">
      <a class="plain" href="${base}/wiki/">Wiki</a>
      <a class="plain" href="${base}/example-setups/">Examples</a>
      <a class="plain" href="${base}/community/">Community</a>
      <a class="btn" href="${base}/sketch/">Open the canvas</a>
    </div>
  </header>`;
}

function referencesBlock(citations) {
  if (!citations || !citations.length) return '';
  return `
      <h2 class="section-head real"><span class="sw"></span>References</h2>
      <ol class="reference-list">
        ${citations.map((c, i) => `<li id="ref-${i + 1}"><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.label)}</a></li>`).join('')}
      </ol>`;
}

// Every embed is the same fixed height by default, which suits a scene that is
// wider than it is tall and squashes one that is not: a three-setup comparison
// stacked vertically fits to a fifth of full size, at which its annotations are
// a few pixels tall. Give the frame the shape of the scene instead, bounded so
// no page ends up scrolling past its own diagram.
const EMBED_WIDTH = 760;
const EMBED_MIN_H = 440;
const EMBED_MAX_H = 900;
// Below this the annotations stop being readable: a 13 px label drawn at a
// fifth of full size is under 3 px tall.
const MIN_LEGIBLE_ZOOM = 0.4;

// How the frame around a scene should be shaped. Returning a style rather
// than a height because a fixed height is the wrong instrument: the article
// is responsive, so the same frame is around 760 px wide on a desktop and
// closer to 320 on a phone, and a height chosen for one leaves the other
// width-limited at exactly the zoom this is trying to avoid -- while an
// inline height would also override the narrow-screen rule in wiki.css and
// make a phone's embed taller without making it any more readable.
//
// An aspect ratio scales with whatever width the frame is actually given, so
// zoomFit lands in the same place at both ends. The cap keeps a tall scene
// from running past a desktop screen; there it becomes height-limited, which
// is the trade worth making.
function embedStyleFor(scene) {
  const points = (scene?.elements || []).filter(el => Number.isFinite(el.x) && Number.isFinite(el.y));
  if (points.length < 2) return '';
  const xs = points.map(el => el.x), ys = points.map(el => el.y);
  const width = Math.max(...xs) - Math.min(...xs) + 200;
  const height = Math.max(...ys) - Math.min(...ys) + 200;
  if (!(width > 0) || !(height > 0)) return '';
  // Leave every embed alone unless the standard height would squash its
  // scene below legibility on the desktop layout.
  const zoomAtDefault = Math.min(EMBED_WIDTH / width, EMBED_MIN_H / height);
  if (zoomAtDefault >= MIN_LEGIBLE_ZOOM) return '';
  return ` style="height: auto; aspect-ratio: ${Math.round(width)} / ${Math.round(height)};`
    + ` max-height: ${EMBED_MAX_H}px; min-height: ${EMBED_MIN_H}px;"`;
}

function pageHTML(entry, manifestEntry, scene) {
  const base = '../..';
  // Only link a related component if it both still exists in the registry
  // and has a built wiki page — same discipline as the wiki's own
  // related-components list, so this never points at a 404.
  const related = (entry.related || []).filter(t => registry[t] && !registry[t].hidden && WIKI_TYPES.has(t));

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${esc(entry.title)} — Examples | OpticalSetup</title>
<meta name="description" content="${esc(entry.tagline)}">
<link rel="canonical" href="${SITE_URL}/example-setups/${manifestEntry.slug}/">
<meta property="og:type" content="article">
<meta property="og:title" content="${esc(entry.title)} — OpticalSetup Examples">
<meta property="og:description" content="${esc(entry.tagline)}">
<meta property="og:url" content="${SITE_URL}/example-setups/${manifestEntry.slug}/">
<meta property="og:image" content="${SITE_URL}/assets/og-image.jpg">
<link rel="icon" href="${FAVICON}">
<link rel="stylesheet" href="${base}/wiki/assets/wiki.css">
<link rel="stylesheet" href="${base}/example-setups/assets/examples.css">
</head>
<body>
${header(base)}
  <div class="wiki-shell" style="grid-template-columns: 1fr;">
    <main class="wiki-article" style="max-width: 760px;">
      <div class="crumb"><a href="${base}/example-setups/">Examples</a>${manifestEntry.group ? ` / ${esc(manifestEntry.group)}` : ''} / ${esc(entry.title)}</div>
      <h1>${esc(entry.title)}</h1>
      <p class="tagline" style="margin-top: 10px;">${esc(entry.tagline)}</p>

      <a class="place-cta" href="${base}/sketch/?example=${encodeURIComponent(manifestEntry.slug)}">Open in the canvas →</a>

      <div class="embed-wrap"${embedStyleFor(scene)}>
        <iframe class="embed-frame" src="${base}/sketch/?example=${encodeURIComponent(manifestEntry.slug)}&amp;embed=1"
          title="${esc(entry.title)} — a live trace of this setup"
          loading="lazy" tabindex="-1" aria-hidden="true"></iframe>
      </div>
      <p class="embed-caption">A live trace of the setup above, shown as a picture. Open it in the canvas to take it apart, retune it, and save or export it as your own.</p>

      ${entry.html ? `
      <h2 class="section-head real"><span class="sw"></span>Background</h2>
      ${entry.html}` : ''}

      <h2 class="section-head sim"><span class="sw"></span>${esc(entry.inOpticalSetupTitle || 'What this setup demonstrates')}</h2>
      <div class="sim-block">
        ${entry.inOpticalSetupHtml || ''}
        ${entry.limitations ? `<div class="limitations"><span class="lbl">What you won't see</span>${entry.limitations}</div>` : ''}
      </div>

      ${related.length ? `
      <h2 class="section-head real"><span class="sw"></span>Related components</h2>
      <div class="related-list">
        ${related.map(t => `<a href="${base}/wiki/${t}/">${iconSVG(t)}${esc(registry[t].label)}</a>`).join('')}
      </div>` : ''}

      ${referencesBlock(entry.citations)}

      ${(entry.resources || []).length ? `
      <h2 class="section-head real"><span class="sw"></span>Further reading</h2>
      <ul class="resource-list">
        ${entry.resources.map(r => `<li><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.label)}</a></li>`).join('')}
      </ul>` : ''}
    </main>
  </div>
  <footer class="wiki-footer">Examples are curated and reviewed for pedagogical accuracy — see the <a href="${base}/community/">community section</a> for setups submitted directly by users, and the <a href="${base}/wiki/">wiki</a> for how each component actually works.</footer>
</body>
</html>
`;
}

function hubHTML(entries) {
  const base = '..';
  const groups = new Map();
  for (const { entry, manifestEntry } of entries) {
    const key = manifestEntry.group || 'Featured';
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ entry, manifestEntry });
  }
  // "Featured" (standalone, no group) first, then groups in first-seen order.
  const groupNames = [...groups.keys()].sort((a, b) => (a === 'Featured' ? -1 : b === 'Featured' ? 1 : 0));

  const cards = ({ entry, manifestEntry }) => `
        <a class="example-card" href="${base}/example-setups/${manifestEntry.slug}/">
          <span class="name">${esc(entry.title)}</span>
          <span class="snippet">${esc(entry.tagline.length > 140 ? `${entry.tagline.slice(0, 140)}…` : entry.tagline)}</span>
        </a>`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Examples — OpticalSetup</title>
<meta name="description" content="Curated optical setups with the real-world background and honest simulation limits behind each one, ready to open in the live canvas.">
<link rel="canonical" href="${SITE_URL}/example-setups/">
<meta property="og:type" content="website">
<meta property="og:title" content="Examples — OpticalSetup">
<meta property="og:description" content="Curated optical setups with the real-world background and honest simulation limits behind each one, ready to open in the live canvas.">
<meta property="og:url" content="${SITE_URL}/example-setups/">
<meta property="og:image" content="${SITE_URL}/assets/og-image.jpg">
<link rel="icon" href="${FAVICON}">
<link rel="stylesheet" href="${base}/wiki/assets/wiki.css">
<link rel="stylesheet" href="${base}/example-setups/assets/examples.css">
</head>
<body>
${header(base)}
  <div class="wiki-shell" style="grid-template-columns: 1fr;">
    <div>
      <div class="hub-hero">
        <h1>Curated optical setups</h1>
        <p>Real interferometer layouts and lab techniques, each with the background physics, an honest note on what OpticalSetup's qualitative tracer won't show you, and a locked live canvas to click through. Reviewed for pedagogical accuracy, unlike the <a href="${base}/community/">community section</a>.</p>
      </div>
      ${entries.length ? groupNames.map(name => `
      <div class="hub-groups">
        <div class="hub-group">
          <h2>${esc(name)}</h2>
          <div class="example-grid">${groups.get(name).map(cards).join('')}</div>
        </div>
      </div>`).join('') : `
      <p class="community-empty">No example pages are published yet.</p>`}
    </div>
  </div>
  <footer class="wiki-footer">More Examples get a page here over time — the full curated set is always available from the in-app Examples menu, whether or not it has a dedicated page yet.</footer>
</body>
</html>
`;
}

async function main() {
  const manifestByName = new Map(examples.map(e => [e.name, e]));

  for (const entry of exampleEntries) {
    if (!manifestByName.has(entry.match)) {
      throw new Error(`examples-content.mjs references unknown example "${entry.match}" — check sketch/js/examples-data.js (run tools/build-examples.mjs first if you just added or renamed an Examples/ file)`);
    }
  }

  const pairs = exampleEntries.map(entry => ({ entry, manifestEntry: manifestByName.get(entry.match) }));

  await mkdir(OUT_DIR, { recursive: true });
  for (const { entry, manifestEntry } of pairs) {
    const pageDir = join(OUT_DIR, manifestEntry.slug);
    await mkdir(pageDir, { recursive: true });
    // The scene itself decides how tall its embed needs to be.
    let scene = null;
    try {
      // manifestEntry.path is URL-encoded and relative to sketch/.
      const relative = decodeURIComponent(manifestEntry.path).replace(/^\.\.\//, '');
      scene = JSON.parse(await readFile(join(ROOT, relative), 'utf-8'));
    } catch (err) {
      // A missing scene is a broken build, not a cosmetic detail: the page
      // would silently get a default-shaped embed for a scene that needs
      // another shape.
      throw new Error(`Could not read the scene for "${manifestEntry.slug}": ${err.message}`);
    }
    await writeFile(join(pageDir, 'index.html'), pageHTML(entry, manifestEntry, scene), 'utf-8');
  }
  await writeFile(join(OUT_DIR, 'index.html'), hubHTML(pairs), 'utf-8');

  console.log(`Built ${pairs.length} example page(s) + index (of ${examples.length} examples in the manifest). Run tools/build-sitemap.mjs next to update sitemap.xml.`);
}

main().catch(err => { console.error(err); process.exitCode = 1; });
